// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _check(address caller, uint64 newNumber, uint64 newTimestamp, uint256 newBasefee, bytes32 newHash, uint64 newSequenceNumber, bytes32 newBatcherHash, uint256 newL1FeeOverhead, uint256 newL1FeeScalar) internal {
        vm.assume(caller != c.DEPOSITOR_ACCOUNT());
        uint64 priorTimestamp;
        try c.timestamp() returns (uint64 __r) { priorTimestamp = __r; } catch { return; }
        vm.assume(address(this) != c.DEPOSITOR_ACCOUNT());
        try c.setL1BlockValues(newNumber, newTimestamp, newBasefee, newHash, newSequenceNumber, newBatcherHash, newL1FeeOverhead, newL1FeeScalar) {} catch { return; }
        uint64 afterTimestamp;
        try c.timestamp() returns (uint64 __r) { afterTimestamp = __r; } catch { return; }
        assertTrue(afterTimestamp != newTimestamp ? true : (afterTimestamp == priorTimestamp));
    }

    function testFuzz_check(address caller, uint64 newNumber, uint64 newTimestamp, uint256 newBasefee, bytes32 newHash, uint64 newSequenceNumber, bytes32 newBatcherHash, uint256 newL1FeeOverhead, uint256 newL1FeeScalar) public {
        _check(caller, newNumber, newTimestamp, newBasefee, newHash, newSequenceNumber, newBatcherHash, newL1FeeOverhead, newL1FeeScalar);
    }

    receive() external payable {}

    fallback() external payable {}
}
